window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4945dfa20243c5ac"]={"versions": [{"id": "FIG-4945dfa20243c5ac", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung der funktionalen Cluster der AUTOSAR Adaptive Platform (ARA) innerhalb der Cluster-Kategorie „Configuration“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei eigenständige Komponenten mit dem Stereotyp <code>«aapFunctionalCluster»</code>:</p>\n<ul class=\"fig-list\"><li><code>Update and Configuration Management</code>: Gekennzeichnet mit dem Entwurfsmerkmal bzw. der Ausprägung <code>daemon-based</code>.\n</li><li><code>Registry</code>: Modelliert als funktionaler Cluster ohne gesonderte Ausprägungsangabe.\n</li></ul>\n<p class=\"fig-p\">Beide Elemente sind als orange hinterlegte UML-Komponenten ohne explizit eingezeichnete Ports, Schnittstellen oder Abhängigkeitsbeziehungen dargestellt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Sequenzen, Kontrollflüsse oder dynamische Interaktionsbeziehungen zwischen den dargestellten Komponenten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die funktionale Gruppierung und Kategorisierung von Plattform-Diensten in der AUTOSAR Adaptive Platform. Für Implementierer und Architekten bedeutet die Kennzeichnung <code>daemon-based</code> bei <code>Update and Configuration Management</code>, dass diese Funktionalität typischerweise als eigenständiger Hintergrundprozess bzw. Dämon auf POSIX-Ebene realisiert wird. <code>Registry</code> ist als regulärer funktionaler Cluster der Plattform klassifiziert.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-067f5db39fc8530a", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung der funktionalen Cluster der AUTOSAR Adaptive Platform (ARA) innerhalb der Cluster-Kategorie „Configuration“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Komponenten:</p>\n<ul class=\"fig-list\"><li><code>«aapFunctionalCluster» Update and Configuration Management</code>: Gekennzeichnet als <code>daemon-based</code> (orange hinterlegt).\n</li><li><code>«aapFunctionalCluster» Vehicle Update and Configuration Management</code>: Gekennzeichnet als <code>daemon-based</code> (orange hinterlegt).\n</li><li><code>Registry</code>: Dargestellt als neutrale UML-Komponente ohne Stereotyp <code>«aapFunctionalCluster»</code> und ohne Hintergrundprozess-Kennzeichnung (hell/weiß hinterlegt).\n</li></ul>\n<p class=\"fig-p\">Es sind keine Ports, Konnektoren oder Schnittstellenbeziehungen modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Sequenzen, Kontrollflüsse oder dynamische Interaktionsbeziehungen zwischen den dargestellten Komponenten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Differenzierung innerhalb der Kategorie „Configuration“: Neben dem lokalen Maschinen-Management (<code>Update and Configuration Management</code>) existiert mit <code>Vehicle Update and Configuration Management</code> eine fahrzeugweite Orchestrierungskomponente, beide jeweils als <code>daemon-based</code> Prozess konzipiert. <code>Registry</code> wird nicht als eigener funktionaler Cluster (<code>«aapFunctionalCluster»</code>) geführt, sondern als eigenständige Komponente im architektonischen Umfeld der Konfigurationsdienste.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-4945dfa20243c5ac", "to": "FIG-067f5db39fc8530a", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Funktionale Cluster: Die Komponente <code>«aapFunctionalCluster» Vehicle Update and Configuration Management</code> (mit der Eigenschaft <code>daemon-based</code>) ist hinzugefügt.\n</li><li>Stereotyp / Zuordnung: Die Komponente <code>Registry</code> verliert das Stereotyp <code>«aapFunctionalCluster»</code> sowie die orange Hinterlegung und ist als neutrale UML-Komponente dargestellt.\n</li></ul>"}]};
